def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split pre-release (after '-')
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(map(int, version_part.split('.')))

        # Parse pre-release identifiers
        if prerelease_part is not None:
            prerelease_ids = prerelease_part.split('.')
            prerelease_tuple = tuple(prerelease_ids)
        else:
            prerelease_tuple = None

        return version_nums, prerelease_tuple

    def compare_prerelease(pre1, pre2):
        # pre1 and pre2 are tuples of identifier strings, or None
        # A version without pre-release sorts after one with pre-release
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # no pre-release sorts after pre-release
        if pre2 is None:
            return -1  # pre-release sorts before no pre-release

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric: compare numerically
                result = int(id1) - int(id2)
                if result != 0:
                    return result
            elif is_num1:
                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric: compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sort first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        else:
            return 0

    def compare_versions(v1, v2):
        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        # Compare MAJOR.MINOR.PATCH
        if parsed1[0] < parsed2[0]:
            return -1
        elif parsed1[0] > parsed2[0]:
            return 1

        # Compare pre-release
        pre_cmp = compare_prerelease(parsed1[1], parsed2[1])
        return pre_cmp

    # Stable sort: preserve input order for equal versions
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    indexed_versions.sort(key=lambda x: (parse_version(x[0])[0], 
                                          lambda pre: (pre is not None, pre if pre is None else tuple((int(id) if id.isdigit() else (1, id)) for id in pre))(parse_version(x[0])[1]),
                                          x[1]))

    return [v for v, _ in indexed_versions]

